/**
 * Port -> trading zone (FE, SEAS, ECI, …), ported from app/logic.py lookup_value() so the web app
 * zones ports exactly like the desktop app. Data: public/zones.json (generated by scripts/build_zones.py).
 * Users can override any port; overrides live in this browser's localStorage.
 */

type ZoneData = {
  zones: string[];
  countries: Record<string, string>;
  aliases: Record<string, string>;
  noise: string;
  ports: Record<string, string | string[]>;
};

export const UNKNOWN = "UNKNOWN";
const OVERRIDES_KEY = "mailai.zoneOverrides";

let data: ZoneData | null = null;
let loading: Promise<ZoneData> | null = null;
let collapsed: Map<string, Set<string>> | null = null;
let keys: string[] = [];
const cache = new Map<string, string>();

export function loadZones(): Promise<ZoneData> {
  loading ??= fetch(new URL("zones.json", new URL(import.meta.env.BASE_URL, location.origin)))
    .then((r) => r.json() as Promise<ZoneData>)
    .then((d) => (initZones(d), d));
  return loading;
}

/** Index zone data (exported separately so tests can supply data without fetch). */
export function initZones(d: ZoneData) {
  data = d;
  cache.clear();
  keys = Object.keys(d.ports).filter((k) => k.length >= 5);
  collapsed = new Map();
  for (const k of keys) {
    const c = collapse(k);
    if (c.length < 5) continue;
    const set = collapsed.get(c) ?? new Set<string>();
    zonesOf(k).forEach((z) => set.add(z));
    collapsed.set(c, set);
  }
}

export const zoneCodes = () => data?.zones ?? [];

export function getOverrides(): Record<string, string> {
  try {
    return JSON.parse(localStorage.getItem(OVERRIDES_KEY) || "{}");
  } catch {
    return {};
  }
}

export function setOverride(port: string, zone: string | null) {
  const o = getOverrides();
  const key = port.trim().toUpperCase();
  if (zone) o[key] = zone;
  else delete o[key];
  localStorage.setItem(OVERRIDES_KEY, JSON.stringify(o));
  cache.clear();
}

const collapse = (s: string) => s.toUpperCase().replace(/[^A-Z0-9]/g, "");
const escapeRe = (s: string) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

function zonesOf(key: string): string[] {
  const v = data!.ports[key];
  return v == null ? [] : Array.isArray(v) ? v : [v];
}

function only(set: Set<string>): string | null {
  return set.size === 1 ? [...set][0] : null;
}

function normalizePort(name: string): string {
  const noise = new RegExp(data!.noise, "i");
  let prev: string | null = null;
  let n = name.trim().toUpperCase();
  while (prev !== n) {
    prev = n;
    n = n.replace(noise, "").trim();
  }
  return n;
}

/** Ratcliff/Obershelp similarity, same measure as Python's difflib.SequenceMatcher.ratio(). */
function ratio(a: string, b: string): number {
  const matches = (s1: string, s2: string): number => {
    if (!s1 || !s2) return 0;
    let best = 0, i1 = 0, i2 = 0;
    for (let i = 0; i < s1.length; i++) {
      for (let j = 0; j < s2.length; j++) {
        let k = 0;
        while (i + k < s1.length && j + k < s2.length && s1[i + k] === s2[j + k]) k++;
        if (k > best) { best = k; i1 = i; i2 = j; }
      }
    }
    if (!best) return 0;
    return best + matches(s1.slice(0, i1), s2.slice(0, i2)) + matches(s1.slice(i1 + best), s2.slice(i2 + best));
  };
  return a.length + b.length ? (2 * matches(a, b)) / (a.length + b.length) : 0;
}

/** Zone for an open location, or UNKNOWN. Call loadZones() first. */
export function zoneFor(location: string | null): string {
  if (!location || !data) return UNKNOWN;
  const input = location.trim().toUpperCase();
  const override = typeof localStorage === "undefined" ? undefined : getOverrides()[input];
  if (override) return override;
  if (cache.has(input)) return cache.get(input)!;
  const z = lookup(input);
  cache.set(input, z);
  return z;
}

function lookup(input: string): string {
  const d = data!;
  if (d.zones.includes(input)) return input;
  if (d.countries[input]) return d.countries[input];
  if (d.aliases[input]) return d.aliases[input];

  const normalized = normalizePort(input);
  const candidates = input === normalized ? [input] : [input, normalized];

  // 1. Exact name.
  for (const c of candidates) {
    const z = only(new Set(zonesOf(c)));
    if (z) return z;
  }
  // 2. Whole-word containment either way ("PORT OF SANTOS" ~ "SANTOS").
  for (const c of candidates) {
    const found = new Set<string>();
    for (const k of keys) {
      if (new RegExp(`\\b${escapeRe(k)}\\b`).test(c) || new RegExp(`\\b${escapeRe(c)}\\b`).test(k)) {
        zonesOf(k).forEach((z) => found.add(z));
        if (found.size > 1) break;
      }
    }
    const z = only(found);
    if (z) return z;
  }
  // 3. Ignoring spaces and punctuation ("GO-GIA" ~ "GOGIA").
  for (const c of candidates) {
    const cc = collapse(c);
    if (cc.length < 5) continue;
    const exact = collapsed!.get(cc);
    if (exact?.size === 1) return [...exact][0];
    const found = new Set<string>();
    for (const [ck, zs] of collapsed!) {
      if (ck.includes(cc)) zs.forEach((z) => found.add(z));
      if (found.size > 1) break;
    }
    const z = only(found);
    if (z) return z;
  }
  // 4. Close spelling (difflib.get_close_matches, cutoff 0.88), only when the best match is unambiguous.
  for (const c of candidates) {
    const scored = keys
      .filter((k) => Math.abs(k.length - c.length) <= Math.ceil(c.length * 0.25))
      .map((k) => [k, ratio(c, k)] as const)
      .filter(([, r]) => r >= 0.88)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 3);
    if (!scored.length) continue;
    const [best, bestRatio] = scored[0];
    const bestZone = only(new Set(zonesOf(best)));
    if (!bestZone) continue;
    const differing = scored.find(([k]) => only(new Set(zonesOf(k))) !== bestZone);
    if (!differing || bestRatio - differing[1] >= 0.05) return bestZone;
  }
  return UNKNOWN;
}
